script:
(function () {
    "use strict";

    window.OvkWallComposer = {
        getWrite: function (element) {
            if (!element) return null;
            return element.id === "write" ? element : element.closest("#write, .wall-form, .ovk-post-form");
        },

        showButtons: function (write) {
            if (!write) return;
            var buttons = write.querySelector(".post-buttons");
            if (buttons) buttons.style.display = "block";
        },

        toggleMenu: function (write) {
            if (!write) return;
            var menu = write.querySelector(".ovk-wall-attachment-menu");
            if (menu) menu.classList.toggle("hidden");
        },

        closeMenu: function (write) {
            if (!write) return;
            var menu = write.querySelector(".ovk-wall-attachment-menu");
            if (menu) menu.classList.add("hidden");
        },

        triggerUpload: function (e, btn, type) {
            if (e) {
                e.preventDefault();
                e.stopPropagation();
            }

            var write = this.getWrite(btn);
            if (!write) return;
            this.closeMenu(write);
            this.showButtons(write);

            this.choosePhotoNative(write);
        },

        choosePhotoNative: function (write) {
            var self = this;
            var form = write.querySelector("form") || write;
            var horizontal = form.querySelector(".post-horizontal");

            if (!horizontal) {
                horizontal = document.querySelector("#write .post-horizontal");
            }

            var input = document.createElement("input");
            input.type = "file";
            input.accept = "image/*";
            input.name = "photo[]";
            input.multiple = true;
            input.style.display = "none";
            document.body.appendChild(input);

            input.addEventListener("change", function () {
                var files = Array.from(input.files || []);
                input.remove();
                if (!files.length) return;

                var contextId = write.dataset.id || document.getElementById("write").dataset.id;
                var formData = new FormData();

                for (var i = 0; i < files.length; i++) {
                    formData.append("photo_" + i, files[i]);
                }
                formData.append("count", files.length);

                var csrfMeta = document.querySelector('meta[name="csrf"]');
                var csrf = (csrfMeta ? (csrfMeta.content || csrfMeta.getAttribute("value")) : "") ||
                           (form.querySelector('input[name="hash"]') || {}).value;
                formData.append("hash", csrf);

                var temporary = document.createElement("div");
                temporary.className = "attachment-item upload-item lagged";
                temporary.innerHTML = '
Загрузка...';
                
                if (horizontal) {
                    horizontal.appendChild(temporary);
                }

                fetch("/photos/upload?upload_context=" + encodeURIComponent(contextId), {
                    method: "POST",
                    body: formData,
                    credentials: "same-origin"
                })
                .then(function (r) { return r.json(); })
                .then(function (res) {
                    if (temporary.parentNode) {
                        temporary.remove();
                    }

                    if (res.success && res.photos) {
                        var hiddenHoriz = form.querySelector('input[name="horizontal_attachments"]');
                        var hiddenAttach = form.querySelector('input[name="attachments"]');
                        
                        if (!hiddenAttach) {
                            hiddenAttach = document.createElement("input");
                            hiddenAttach.type = "hidden";
                            hiddenAttach.name = "attachments";
                            hiddenAttach.value = "";
                            form.appendChild(hiddenAttach);
                        }

                        res.photos.forEach(function (ph) {
                            var descriptor = ph.target || ("photo" + (ph.pretty_id || ph.id));

                            if (hiddenHoriz) {
                                var hList = hiddenHoriz.value ? hiddenHoriz.value.split(",").filter(Boolean) : [];
                                if (hList.indexOf(descriptor) === -1 && hList.indexOf(String(ph.pretty_id)) === -1) {
                                    hList.push(descriptor);
                                }
                                hiddenHoriz.value = hList.join(",");
                            }

                            if (hiddenAttach) {
                                var aList = hiddenAttach.value ? hiddenAttach.value.split(",").filter(Boolean) : [];
                                if (aList.indexOf(descriptor) === -1) {
                                    aList.push(descriptor);
                                }
                                hiddenAttach.value = aList.join(",");
                            }

                            var thumb = document.createElement("div");
                            thumb.className = "attachment-item upload-item";
                            thumb.innerHTML = '';

                            var removeBtn = document.createElement("a");
                            removeBtn.href = "javascript:void(0)";
                            removeBtn.className = "remove-attach";
                            removeBtn.innerHTML = "×";
                            removeBtn.onclick = function (e) {
                                e.stopPropagation();
                                thumb.remove();

                                if (hiddenHoriz) {
                                    hiddenHoriz.value = hiddenHoriz.value.split(",").filter(function (val) {
                                        return val !== descriptor && val !== String(ph.pretty_id);
                                    }).join(",");
                                }

                                if (hiddenAttach) {
                                    hiddenAttach.value = hiddenAttach.value.split(",").filter(function (val) {
                                        return val !== descriptor;
                                    }).join(",");
                                }
                            };
                            thumb.appendChild(removeBtn);

                            if (horizontal) {
                                horizontal.appendChild(thumb);
                            }
                        });

                        self.showButtons(write);
                    }

                })
                .catch(function (err) {
                    if (temporary.parentNode) {
                        temporary.remove();
                    }
                    alert("Ошибка сети: " + err.message);
                });
            });

            input.click();
        }

    };

    function initEvents() {
        document.querySelectorAll(".ovk-post-form textarea").forEach(function (t) {
            if (t.dataset.bound) return;
            t.dataset.bound = "1";
            var open = function () {
                var w = OvkWallComposer.getWrite(t);
                OvkWallComposer.showButtons(w);
            };
            t.addEventListener("focus", open);
            t.addEventListener("click", open);
            t.addEventListener("input", open);
        });

        document.querySelectorAll(".menu_toggler").forEach(function (b) {
            if (b.dataset.bound) return;
            b.dataset.bound = "1";
            b.addEventListener("click", function (e) {
                e.preventDefault();
                e.stopPropagation();
                var w = OvkWallComposer.getWrite(b);
                OvkWallComposer.toggleMenu(w);
            });
        });

        document.addEventListener("click", function (e) {
            if (!e.target.closest(".ovk-wall-attachment-area")) {
                document.querySelectorAll(".ovk-wall-attachment-menu").forEach(function (m) {
                    m.classList.add("hidden");
                });
            }
        });
    }

    if (document.readyState === "loading") {
        document.addEventListener("DOMContentLoaded", initEvents);
    } else {
        initEvents();
    }
})();
